describe('File Upload Retry Functionality', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully retry a failed upload without re-selecting the file', () => {
    // Setup: intercept the initial upload request
    cy.intercept('POST', '/api/upload').as('initialUpload');

    // Select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf');

    // Trigger upload
    cy.get('[data-testid="upload-button"]').click();

    // Wait for initial upload attempt
    cy.wait('@initialUpload').then((interception) => {
      expect(interception.response.statusCode).to.equal(500);
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Upload failed');

    // Verify retry button is visible
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Setup: intercept the retry request
    cy.intercept('POST', '/api/upload').as('retryUpload');

    // Wait for retry upload
    cy.wait('@retryUpload').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Upload successful');

    // Verify file input value is still present (not cleared)
    cy.get('[data-testid="file-input"]').should('have.value', 'cypress/fixtures/test-file.pdf');
  });

  it('should not retry if retry button is not visible or file is not selected', () => {
    // Setup: intercept the initial upload request
    cy.intercept('POST', '/api/upload').as('initialUpload');

    // Navigate to upload page without selecting a file
    cy.visit('/upload');

    // Attempt to trigger upload without file
    cy.get('[data-testid="upload-button"]').click();

    // Verify validation error appears
    cy.get('[data-testid="validation-error"]').should('be.visible').should('contain', 'Please select a file');

    // Verify retry button does not appear
    cy.get('[data-testid="retry-button"]').should('not.exist');

    // Select a file and trigger upload to fail
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf');
    cy.get('[data-testid="upload-button"]').click();

    cy.wait('@initialUpload').then((interception) => {
      expect(interception.response.statusCode).to.equal(500);
    });

    // Verify retry button appears after failure
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click retry button and verify it fails again (edge case: persistent failure)
    cy.get('[data-testid="retry-button"]').click();
    cy.intercept('POST', '/api/upload').as('retryUploadFail');
    cy.wait('@retryUploadFail').then((interception) => {
      expect(interception.response.statusCode).to.equal(500);
    });

    // Verify error message persists
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Upload failed');
  });
});
